const STORAGE_KEY = 'kora.preview.v1';
const PERSONA_IDS = ['calm','snark','fiery','gentle'];
const ACTIVITY_IDS = ['cardio','strength','stretch','walk'];
const calendar=window.KoraDaily;
const lifestyle=window.KoraLifestyle;
const profileDefaults=()=>({name:'',height:'',weight:'',persona:'',activities:[],minutes:'20',goal:'routine',noJump:true});
const freshState=()=>{const value=calendar.load(null);value.profile=profileDefaults();value.onboarded=false;value.language='zh';return value;};
let state=freshState(),storageOK=true;
function validProfile(p) { return p && typeof p.name==='string' && p.name.trim().length>0 && p.name.trim().length<=20 && PERSONA_IDS.includes(p.persona) && (p.height===''||(Number.isFinite(Number(p.height))&&Number(p.height)>=80&&Number(p.height)<=250)) && (p.weight===''||(Number.isFinite(Number(p.weight))&&Number(p.weight)>=20&&Number(p.weight)<=400)) && Array.isArray(p.activities) && p.activities.some(a=>ACTIVITY_IDS.includes(a)) && ['10','20','30'].includes(String(p.minutes)); }
try {
 const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));
 if(saved){state=calendar.load(saved);state.profile={...profileDefaults(),...state.profile};
  state.profile.activities=Array.isArray(state.profile.activities)?state.profile.activities.filter(a=>ACTIVITY_IDS.includes(a)):[];
  if(!['routine','regular','energy'].includes(state.profile.goal))state.profile.goal='routine';
  state.profile.lifestyle=lifestyle.valid(state.profile.lifestyle)?lifestyle.result(state.profile.lifestyle.answers):null;
  state.language=state.language==='en'?'en':'zh';state.onboarded=Boolean(state.onboarded&&validProfile(state.profile));
 }
}catch{storageOK=false;}
let weekOffset=0;
let currentRoute='today',filter='all',draft=null,modalView=null,motion=null,lastAnimatedRoute=null,toastTimer=null,modalOpener=null;
let companionDispose=null;
let setupStep=1,setupDraft=structuredClone(state.profile),profileDraft=null;
let quizSession=null,lifePlanDraft=null;
try{const q=JSON.parse(sessionStorage.getItem('kora.quiz.draft'));if(q&&['intro','questions','result'].includes(q.phase)&&Array.isArray(q.answers)&&q.answers.length<=6&&q.answers.every((a,i)=>a==null||lifestyle.questions[i].options.some(o=>o.id===a))&&Number.isInteger(q.index)&&q.index>=0&&q.index<6&&(q.phase!=='result'||lifestyle.result(q.answers)))quizSession=q;}catch{}
const chats=[];
const t=(zh,en)=>state.language==='en'?en:zh;
const pair=a=>a[state.language==='en'?1:0];
