function persona(id=state.profile.persona){return personaData[id]||personaData.calm;}
function say(topic,id=state.profile.persona){return pair(persona(id).line[topic]||persona(id).line.fallback);}
function portrait(id=state.profile.persona,cls='',alt=''){return `<img class="${cls}" src="assets/kora-${PERSONA_IDS.includes(id)?id:'calm'}-sport${['snark','fiery'].includes(id)?'-v4':'-v2'}.png" alt="${escapeHTML(alt||t('Kora '+pair(persona(id).label),pair(persona(id).label)+' Kora'))}">`;}
function applyTone(id=state.profile.persona){const p=persona(id);document.documentElement.style.setProperty('--green',p.color);document.documentElement.style.setProperty('--soft',p.soft);}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageOK=true;return true;}catch{storageOK=false;return false;}}
function toast(text){$('#toast').innerHTML=portrait(state.profile.persona,'toast-kora','')+`<span>${escapeHTML(text)}</span>`;$('#toast').classList.add('toast-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('toast-visible'),4200);}
function persistNotice(text){toast(save()?text:t('浏览器暂时无法保存；当前改动仅在本次页面保留。','Storage is unavailable. Changes last only for this session.'));}
const navItems=[['today','home',['今天','Today']],['food','bowl',['饮食','Food']],['move','move',['运动','Move']],['chat','chat',['聊聊','Chat']],['profile','user',['档案','Profile']]];
function refreshDate(){if(calendar.dateKey()===state.date)return false;captureForm();if($('#modal').open)closeModal();calendar.activate(state,calendar.dateKey());weekOffset=0;save();render();toast(t('新的一天开始了，昨天的记录已保留。','A new day. Yesterday’s records are saved.'));return true;}
function route(name){if(!navItems.some(n=>n[0]===name))name='today';if(currentRoute!==name)profileDraft=null;location.hash=name;if(currentRoute===name)render();}
function intro(kicker,title,description){return `<div class="page-intro"><p class="eyebrow">${kicker}</p><h1>${title}</h1><p>${description}</p></div>`;}
function koraNote(topic){return `<div class="kora-note">${portrait(state.profile.persona,'note-kora')}<div><small>${pair(persona().label)} Kora</small><p>${say(topic)}</p></div></div>`;}
function languageControl(){return `<div class="language-switch" role="group" aria-label="${t('语言','Language')}"><button data-lang="zh" lang="zh-CN" aria-pressed="${state.language==='zh'}">中文</button><span aria-hidden="true">/</span><button data-lang="en" lang="en" aria-pressed="${state.language==='en'}">EN</button></div>`;}
function render(){
 companionDispose?.();companionDispose=null;
 motion?.revert(); currentRoute=location.hash.slice(1)||'today';if(!navItems.some(n=>n[0]===currentRoute))currentRoute='today';
 document.body.classList.toggle('quiz-mode',Boolean(quizSession)||(!state.onboarded&&!lifestyle.valid(setupDraft.lifestyle)));
 document.documentElement.lang=state.language==='en'?'en':'zh-CN';document.body.classList.toggle('onboarding',!state.onboarded);applyTone(state.onboarded?state.profile.persona:setupDraft.persona);
 $('.skip-link').textContent=t('跳到主要内容','Skip to content');$('.brand').setAttribute('aria-label',t('Kora 首页','Kora home'));
 $('.header-tools').innerHTML=languageControl()+(state.onboarded?`<button class="profile-button" data-route="profile" aria-label="${t('打开我的档案','Open my profile')}">${portrait(state.profile.persona,'')}<strong>${escapeHTML(state.profile.name)}</strong></button>`:'');
 const nav=state.onboarded?navItems.map(([id,glyph,label])=>`<a href="#${id}" class="nav-item ${id===currentRoute?'active':''}" ${id===currentRoute?'aria-current="page"':''}>${icon(glyph)}<span>${pair(label)}</span></a>`).join(''):'';
 $('.desktop-nav').innerHTML=nav;$('.mobile-nav').innerHTML=nav;$('.desktop-nav').setAttribute('aria-label',t('主导航','Main navigation'));$('.mobile-nav').setAttribute('aria-label',t('移动端主导航','Mobile navigation'));
 const label=quizSession?t('生活人格测试','Your Kora type'):state.onboarded?pair(navItems.find(n=>n[0]===currentRoute)[2]):t('认识你的 Kora','Meet your Kora');document.title=label+' · Kora';$('#page-label').textContent=label;
 $('.footer').innerHTML=`<span>Kora · ${t('断了，也接得上。','A pause is not the end.')}</span><button data-action="about">${t('关于预览版','About this preview')}</button>`;
 $('#main').innerHTML=quizSession?quizView():state.onboarded?({today,food,move,chat,profile}[currentRoute])():onboarding();
 animatePage();companionDispose=window.KoraCompanion?.mount($('#main'));if(currentRoute==='chat'&&state.onboarded)$('#messages').scrollTop=$('#messages').scrollHeight;
}
function animatePage(){
 if(!window.gsap)return;
 const root=$('#main');
 const key=(state.onboarded?currentRoute:'setup'+setupStep)+':'+state.language;
 const enter=lastAnimatedRoute!==key;lastAnimatedRoute=key;
 motion=gsap.matchMedia();
 motion.add('(prefers-reduced-motion: no-preference)',()=>{
  if(!enter)return;
  const tl=gsap.timeline({defaults:{duration:.65,ease:'power3.out',clearProps:'transform,opacity,visibility'}});
  const add=(selector,vars,position)=>{const nodes=root.querySelectorAll(selector);if(nodes.length)tl.from(nodes,vars,position);};
  add('.greeting,.page-intro .eyebrow,.setup-intro .eyebrow',{y:10,autoAlpha:0},0);
  add('.headline-line>span,.page-intro h1,.setup-intro h1',{y:30,autoAlpha:0,stagger:.12},.07);
  add('.headline-stroke',{scaleX:0,transformOrigin:'left center',duration:.7},.48);
  add('.hero-description,.hero-actions,.page-intro>p:last-child,.setup-intro>p:last-child',{y:12,autoAlpha:0,stagger:.07},.28);
  add('.hero-kora,.setup-companion>img',{y:16,autoAlpha:0,scale:.97,duration:.85},.16);
  add('.hero-wordmark,.hero-caption',{y:10,autoAlpha:0,stagger:.1},.4);
  add('.setup .persona-card',{y:16,autoAlpha:0,stagger:.055},.22);
 },root);
 // Pre-create reversible interactions inside the media context; clean up on every render.
 motion.add('(prefers-reduced-motion: no-preference) and (hover: hover)',()=>{
  const cleanups=[];
  root.querySelectorAll('.persona-card').forEach((card,index)=>{
   const tween=gsap.to(card.querySelector('.persona-art img'),{y:-7,rotation:index%2?1.5:-1.5,duration:.32,ease:'power2.out',paused:true});
   const enter=()=>tween.play();
   const leave=()=>{if(!card.matches(':hover')&&!card.contains(document.activeElement))tween.reverse();};
   [['pointerenter',enter],['pointerleave',leave],['focusin',enter],['focusout',leave]].forEach(([event,handler])=>{
    card.addEventListener(event,handler);cleanups.push(()=>card.removeEventListener(event,handler));
   });
  });
  return ()=>cleanups.forEach(fn=>fn());
 },root);
}
function activityLabel(id){return pair({cardio:['有氧','Cardio'],strength:['力量','Strength'],stretch:['舒展 / 瑜伽','Stretch / yoga'],walk:['散步','Walking']}[id]||['运动','Movement']);}
function goalLabel(id){return pair({routine:['养成舒服的生活节奏','Build a comfortable routine'],energy:['提高体能与精力','Build fitness and energy'],regular:['规律吃饭和活动','Eat and move regularly']}[id]||['养成舒服的生活节奏','Build a comfortable routine']);}
function personaCards(selected,compact=false){return `<div class="persona-grid ${compact?'compact':''}" role="group" aria-label="${t('选择考拉性格','Choose Kora’s personality')}">${PERSONA_IDS.map((id,i)=>`<button type="button" class="persona-card ${selected===id?'selected':''}" style="--persona-soft:${persona(id).soft};--persona-color:${persona(id).color}" data-persona="${id}" aria-pressed="${selected===id}"><div class="persona-art">${portrait(id)}<span class="persona-check" aria-hidden="true">${selected===id?'✓':'+'}</span></div><div class="persona-copy"><small>0${i+1}</small><h2>${pair(persona(id).label)}</h2><p>${pair(persona(id).tag)}</p>${!compact?`<blockquote>“${say('return',id)}”</blockquote>`:''}</div></button>`).join('')}</div>`;}
function onboarding(){if(!lifestyle.valid(setupDraft.lifestyle))return quizView();return `<section class="setup"><div class="setup-progress" aria-label="${t('首次设置进度','Setup progress')}"><span class="active">✓ ${t('生活人格','Your style')} · 02 ${t('选一只 Kora','Your Kora')}</span><i></i><span class="${setupStep===2?'active':''}">03 ${t('认识你','About you')}</span></div>${setupStep===1?`<div class="setup-intro"><p class="eyebrow">${t('想放弃时，你想听见谁？','WHO DO YOU NEED WHEN IT GETS HARD?')}</p><h1>${t('你想和哪一只，<br>一起开始？','Who is your<br>kind of Kora?')}</h1><p>${t('四种把你接回来的方式。以后想换，去档案里就好。','Four ways to help you carry on. Switch anytime in Profile.')}</p></div>${personaCards(setupDraft.persona)}<div class="setup-bottom"><p>${t('嘴上可以有脾气，陪伴始终站你这边。','A little attitude. Always on your side.')}</p><button class="primary" data-action="setup-next" ${!PERSONA_IDS.includes(setupDraft.persona)?'disabled':''}>${setupDraft.persona?t('就选'+pair(persona(setupDraft.persona).label)+' Kora','Continue with '+pair(persona(setupDraft.persona).label)+' Kora'):t('先选一只 Kora','Choose a Kora first')} ${icon('arrow')}</button></div>`:`<div class="setup-details"><aside class="setup-companion">${portrait(setupDraft.persona)}<span class="persona-badge">${pair(persona(setupDraft.persona).label)} Kora</span><h2>${t('好，现在认识你。','Now, a little about you.')}</h2><p>“${say('hello',setupDraft.persona)}”</p><button class="text-link" data-action="setup-back">← ${t('重新选性格','Choose another personality')}</button></aside><section class="setup-form"><div class="setup-intro"><h1>${t('从你的日常开始。','Start with your everyday.')}</h1><p>${t('填好这一次，就会同步到「我的档案」。','Save these once. They will be ready in your Profile.')}</p></div><form id="setup-form" novalidate>${profileFields(setupDraft)}<p class="data-note">${icon('shield')}<span>${t('身高、体重和偏好仅保存在这个浏览器。不会上传或用于生成减重处方；你可以在档案中修改或清除。','Your measurements and preferences stay in this browser. They are not uploaded or used to prescribe weight loss. Edit or clear them in Profile.')}</span></p><p class="form-error" id="form-error" role="alert"></p><button class="primary" type="submit">${t('保存资料，开始吧','Save & start')} ${icon('arrow')}</button></form></section></div>`}</section>`;}
function profileFields(p){return `<div class="form-grid"><div class="field"><label class="label" for="profile-name">${t('怎么称呼你','What should we call you?')}</label><input id="profile-name" name="name" autocomplete="nickname" maxlength="20" value="${escapeHTML(p.name)}" placeholder="${t('你的昵称','Your name')}" required></div><div class="field"><label class="label" for="profile-time">${t('通常能留给运动的时间','Time for movement')}</label><select id="profile-time" name="minutes">${['10','20','30'].map(n=>`<option value="${n}" ${String(p.minutes)===n?'selected':''}>${n} ${t('分钟','minutes')}</option>`).join('')}</select></div><div class="field"><label class="label" for="profile-height">${t('身高','Height')} <span>cm</span></label><input id="profile-height" name="height" type="number" inputmode="decimal" min="80" max="250" step="0.1" value="${escapeHTML(p.height)}" placeholder="${t('可稍后填写','Optional')}"></div><div class="field"><label class="label" for="profile-weight">${t('体重','Weight')} <span>kg</span></label><input id="profile-weight" name="weight" type="number" inputmode="decimal" min="20" max="400" step="0.1" value="${escapeHTML(p.weight)}" placeholder="${t('可稍后填写','Optional')}"></div></div><fieldset class="activity-field"><legend>${t('你想做哪些运动？','What do you enjoy?')} <small>${t('可多选','Choose one or more')}</small></legend><div class="activity-options">${ACTIVITY_IDS.map(id=>`<label><input name="activities" type="checkbox" value="${id}" ${p.activities.includes(id)?'checked':''}><span>${activityLabel(id)}</span></label>`).join('')}</div></fieldset><div class="field"><label class="label" for="profile-goal">${t('目前想照顾好的事情','What matters to you right now?')}</label><select id="profile-goal" name="goal">${['routine','regular','energy'].map(id=>`<option value="${id}" ${p.goal===id?'selected':''}>${goalLabel(id)}</option>`).join('')}</select></div><label class="checkbox-line"><input type="checkbox" name="noJump" id="profile-nojump" ${p.noJump?'checked':''}>${t('优先选择不跳跃的运动','Prefer movement without jumping')}</label>`;}
function readProfileForm(base){return {...base,name:$('#profile-name').value.trim(),height:$('#profile-height').value,weight:$('#profile-weight').value,minutes:$('#profile-time').value,goal:$('#profile-goal').value,noJump:$('#profile-nojump').checked,activities:[...document.querySelectorAll('input[name="activities"]:checked')].map(e=>e.value)};}
function captureForm(){if(!$('#profile-name'))return;if(!state.onboarded)setupDraft=readProfileForm(setupDraft);else if(currentRoute==='profile')profileDraft=readProfileForm(profileDraft||state.profile);}
function profileError(p){if(!PERSONA_IDS.includes(p.persona))return t('先选一只 Kora。','Choose your Kora first.');if(!p.name.trim()||p.name.length>20)return t('请输入1—20个字的昵称。','Enter a name of 1–20 characters.');if(p.height!==''&&(!Number.isFinite(Number(p.height))||Number(p.height)<80||Number(p.height)>250))return t('请确认身高，填写80—250之间的数值（cm）。','Check your height: enter a number from 80 to 250 cm.');if(p.weight!==''&&(!Number.isFinite(Number(p.weight))||Number(p.weight)<20||Number(p.weight)>400))return t('请确认体重，填写20—400之间的数值（kg）。','Check your weight: enter a number from 20 to 400 kg.');if(!p.activities.length)return t('至少选一种你想尝试的运动。','Choose at least one kind of movement.');return '';}

const issueLabels={time:['今天没时间','Short on time'],tired:['今天不想练','Need a rest'],return:['我又想放弃了','I feel like giving up'],guilt:['吃完有点自责','Feeling food guilt']};
const issueSubs={time:['把计划调小一点','Make the plan smaller'],tired:['休息也是一种选择','Rest is an option'],return:['不补账，直接回来','Return without catching up'],guilt:['先对自己温柔一点','A little kindness first']};
const issueIcons={time:'clock',tired:'moon',return:'refresh',guilt:'heart'};
function planTitle(p=state.plan){if(p.type==='starter')return t(`${p.minutes} 分钟${activityLabel(p.action)} · 轻量开始`,`${p.minutes} min ${activityLabel(p.action).toLowerCase()} · an easy start`);if(p.type==='tiny')return smallTitle(p);if(p.type==='rest')return t('今天，安心休息','A proper rest day');if(p.type==='reschedule')return t(`${p.minutes} 分钟训练 · 留给明天`,`${p.minutes}-minute session · tomorrow`);if(p.type==='short')return t('10 分钟轻活动','10 minutes of gentle movement');const w=workouts.find(w=>w.id===p.workout)||workouts[0];return t(`${p.minutes} 分钟${pair(w.name)}`,`${p.minutes}-minute ${pair(w.name).toLowerCase()}`);}
function planWhen(p=state.plan){return `${p.type==='reschedule'?displayDate(p.targetDate||calendar.addDays(state.date,1)):t('今天','Today')} · ${p.minutes?t(p.minutes+' 分钟',p.minutes+' min'):t('休息','Rest')}`;}
function reminderText(){if(state.plan.done)return t('已完成 · 训练提醒已取消','Done · workout reminder removed');if(state.plan.type==='reschedule')return t('今晚取消 · 明天 20:00','Not tonight · tomorrow at 20:00');if(!state.plan.reminder)return t('今晚训练提醒已取消','Tonight’s workout reminder removed');return t('今晚 20:00 · 今天的安排','Tonight at 20:00 · today’s plan');}
function displayDate(key){return calendar.parseDate(key).toLocaleDateString(state.language==='en'?'en-US':'zh-CN',{month:'short',day:'numeric',weekday:'short'});}
function dayStatus(day){if(!day)return t('未记录','No record');if(day.plan?.done)return t('已完成','Done');if(day.plan?.type==='rest')return t('休息','Rest');if(day.plan?.type==='reschedule')return t('已改期','Moved');if(day.plan)return day.plan.minutes+t('分钟',' min');return day.logs.length?t('有餐食','Meal logged'):t('未安排','Open');}
function weekStrip(){const labels=t(['一','二','三','四','五','六','日'],['M','T','W','T','F','S','S']);const dates=calendar.weekDates(calendar.addDays(state.date,weekOffset*7));return `<div class="week-controls"><button data-week="-1" aria-label="${t('查看上一周','Previous week')}">← ${t('上周','Prev')}</button><span>${dates[0]} — ${dates[6]}</span><button data-week="1" aria-label="${t('查看下一周','Next week')}">${t('下周','Next')} →</button></div>${weekOffset?`<button class="text-link" data-action="this-week">${t('回到本周','This week')}</button>`:''}<div class="week-strip">${dates.map((key,i)=>{const day=state.days[key],status=dayStatus(day);return `<button class="day ${key===state.date?'today':''} ${day?.plan?.done?'done':''} ${day?.plan?'scheduled':''}" data-history-date="${key}" aria-label="${displayDate(key)} · ${status}" ${key===state.date?'aria-current="date"':''}><small>${labels[i]}</small><b>${calendar.parseDate(key).getDate()}</b><span class="day-dot"></span><small class="day-status">${status}</small></button>`;}).join('')}</div>`;}
function historySummary(){const keys=Object.keys(state.days).filter(k=>k<state.date).sort().reverse().slice(0,7);return `<div class="memory-note"><p>${t('过去的记录，留在它发生的那一天。','Every day keeps its own story.')}</p>${keys.length?keys.map(k=>`<button data-history-date="${k}">${displayDate(k)} · ${dayStatus(state.days[k])} ↗</button>`).join(''):`<small>${t('从今天开始积累，点击周历查看每日记录。','Start today. Select a date to see its records.')}</small>`}${state.legacy?`<button data-action="legacy">${t('查看旧版无日期记录','View undated earlier records')} ↗</button>`:''}</div>`;}
function historyMeals(logs){return logs.length?logs.map(l=>`<p>${escapeHTML(foodName(l))} · ${escapeHTML(l.grams)} g · ${escapeHTML(l.cal)} kcal</p>`).join(''):`<p>${t('没有餐食记录。','No meal entries.')}</p>`;}
function showHistory(key){if(!/^\d{4}-\d{2}-\d{2}$/.test(key))return;const day=state.days[key];openModal(modalShell(`<h2 id="modal-title">${displayDate(key)}</h2><p class="modal-sub">${dayStatus(day)}</p>${day?.plan?`<p>${planTitle(day.plan)}</p>`:''}${day?.comeback?`<p>${t('当天状态：','Energy: ')}${pair(energyData[day.comeback.energy]?.title||['已记录','Recorded'])} · ${day.comeback.done?t('已照顾自己','Care recorded'):t('已确认安排','Arrangement confirmed')}</p>`:''}${day?historyMeals(day.logs):''}<button class="primary" data-action="close">${t('知道了','Done')}</button>`,t('每日记录','Daily records')),'history:'+key);}
function showLegacy(){const old=state.legacy;if(!old)return;openModal(modalShell(`<h2 id="modal-title">${t('旧版无日期记录','Earlier undated records')}</h2><p class="modal-sub">${t('这些旧记录没有可靠日期，单独保留，不计入今天。','These older records have no reliable date. They are kept separately from today.')}</p><p>${old.plan?planTitle(old.plan):''}</p>${historyMeals(old.logs||[])}<button class="primary" data-action="close">${t('知道了','Done')}</button>`,t('旧版记录','Earlier records')),'legacy');}
const comeback=window.KoraComeback;
let comebackDraft=null;
const energyData={
 ready:{title:['有点劲儿','Some energy'],sub:['按自己的节奏，接着走','Carry on at your own pace'],glyph:'sun',tag:['一起动一动','Let’s move together']},
 low:{title:['只剩一点电','Running low'],sub:['把今天缩成一个小动作','Make today one small action'],glyph:'leaf',tag:['小一点，也算数','Small still counts']},
 rest:{title:['今天撑不住','I need a pause'],sub:['先放下训练，照顾自己','Set training aside. Care for yourself.'],glyph:'moon',tag:['今天，陪你歇一会','I’ll sit with you today']}
};
function smallTitle(p){return p.type==='tiny'?p.action==='walk'?t('走动 2 分钟','Walk for 2 minutes'):t('轻轻舒展 1 分钟','Gently stretch for 1 minute'):planTitle(p);}
function todayCare(){return state.days[state.date].comeback;}
function energyChoices(){return `<section class="energy-section" aria-labelledby="energy-title"><div class="section-head"><div><p class="section-number">01 / ${t('先照顾今天的你','MEET YOURSELF TODAY')}</p><h2 id="energy-title">${t('今天，还剩多少电？','How much energy is left today?')}</h2></div><span class="energy-helper">${t('没有标准答案。也不急着变好。','No right answer. No rush to feel better.')}</span></div><div class="energy-grid">${Object.entries(energyData).map(([id,e],i)=>`<button class="energy-choice energy-${id}" data-energy="${id}"><span class="energy-meter" aria-hidden="true">${[0,1,2].map(n=>`<i class="${n<3-i?'charged':''}"></i>`).join('')}</span><span class="energy-copy"><strong>${pair(e.title)}</strong><small>${pair(e.sub)}</small></span><span class="energy-arrow" aria-hidden="true">↗</span></button>`).join('')}</div><p class="energy-foot">${t('先说说原因，再一起确认。选择状态不会立刻改掉你的计划。','Tell me a little, then we decide together. Choosing a mood won’t change your plan.')}</p></section>`;}
function anchorCard(){const c=todayCare();if(!c)return energyChoices();const done=c.done||state.plan.done,rest=state.plan.type==='rest',moved=state.plan.type==='reschedule';return `<section class="anchor-card ${done?'anchor-done':''}" aria-labelledby="anchor-title"><div class="anchor-copy"><p class="section-number">01 / ${done?t('这一小步，已经留下了','A SMALL STEP, NOW PART OF YOUR STORY'):t('今天，只留这一件','JUST THIS ONE THING TODAY')}</p><h2 id="anchor-title">${done?t('这样，就很好。','That is enough.'):rest?t('给自己留一小段空白','Leave a little room for yourself'):smallTitle(state.plan)}</h2><p>${done?returnMessage():rest?t('坐一会，放下催促。今天不补练，饮食照常。','Sit for a moment. Let the pressure go. No catch-up exercise; eat as usual.'):moved?t('今天留白，安排已留给明天。','A little space today. Your session is saved for tomorrow.'):t('做完就可以停，不需要再加码。不舒服时随时停下来。','You can stop when you’re done. No extra tasks. Stop whenever you feel uncomfortable.')}</p></div><div class="anchor-actions">${!done&&!moved?`<button class="primary" data-action="comeback-complete">${icon(rest?'heart':'check')}${rest?t('我照顾过自己了','I made room for myself'):t('这一小步，做到了','I did my little step')}</button>`:`<span class="anchor-stamp">${icon(done?'check':'moon')}${done?t('已留在你的路上','Saved on your path'):t('今天不用补','No catching up today')}</span>`}${!done?`<button class="text-link" data-action="comeback-energy">${t('还是太多？再调小一点','Still too much? Adjust again')}</button>`:''}${state.undo?`<button class="text-link" data-action="undo">${t('撤销刚才的安排','Undo this arrangement')} ↶</button>`:''}</div></section>`;}
function returnMessage(){const insight=comeback.returnInsight(state);if(!insight)return t('不是连续多少天，是今天你又照顾了自己一次。','No streak to protect. Today, you cared for yourself again.');if(insight.previous!==null&&insight.days<insight.previous)return t(`两次行动记录之间，这次空了 ${insight.days} 天，上一次是 ${insight.previous} 天。你在找到接回来的节奏。`,`Between recorded actions: ${insight.days} unrecorded days this time, ${insight.previous} last time. You’re finding your way back.`);return t(`中间有 ${insight.days} 天没有行动记录。今天，你又留下了一小步。`,`There were ${insight.days} days without a recorded action. Today, you left another small step.`);}
function pathSection(){const records=comeback.records(state).slice(-7);const labels={action:['动了一点','A little movement'],care:['照顾了自己','A moment of care'],rest:['选择休息','Chose rest'],checkin:['接上今天','Checked in'],adjust:['调整了安排','Adjusted the plan'],meal:['好好吃饭','A meal recorded']};return `<section class="return-path"><div class="section-head"><div><p class="section-number">02 / ${t('不清零，也不催促','NOTHING RESETS HERE')}</p><h2>${t('你回来过的路。','Your way back, a little at a time.')}</h2></div><span class="path-leaf">${icon('leaf')}</span></div><p class="path-intro">${t('运动、休息、调整，都可以留下。空白的日子，不替你判断。','Movement, rest, adjustments: all can belong here. Blank days stay blank, without judgment.')}</p>${records.length?`<ol class="path-track">${records.map((r,i)=>`<li><button data-history-date="${r.date}" class="path-stop ${r.done?'has-action':''}"><span class="path-mark">${icon(r.kind==='care'||r.kind==='rest'?'moon':r.kind==='meal'?'bowl':r.done?'leaf':'refresh')}</span><small>${displayDate(r.date)}</small><strong>${pair(labels[r.kind])}</strong></button>${i<records.length-1&&comeback.gap(r.date,records[i+1].date)>0?`<span class="path-gap">${comeback.gap(r.date,records[i+1].date)} ${t('天空白','blank days')}</span>`:''}</li>`).join('')}</ol>`:`<div class="path-empty"><span class="empty-start">${icon('leaf')}</span><div><strong>${t('从你的第一条真实记录开始。','Your first real record starts the path.')}</strong><p>${t('确认一个安排，或记录一次行动，它就会留在这里。今天只是来看看，也可以。','Confirm an arrangement or record an action and it will appear here. Just looking around today is okay, too.')}</p></div></div>`}<p class="path-note">${t('只展示本浏览器已保存的记录；空白不代表你没有行动。','Only records saved in this browser. A blank does not mean you did nothing.')}</p></section>`;}
function startComeback(energy){if(state.plan.done||todayCare()?.done){startIssue('return');return;}comebackDraft=comeback.begin(state,energy);if(comebackDraft)showComebackReason();}
function showComebackEnergy(){openModal(modalShell(`<h2 id="modal-title">${t('那就，再轻一点。','Let’s make more room.')}</h2><p class="modal-sub">${t('可以继续缩小，也可以直接休息。确认前，已有安排保持不变。','Make it smaller, or simply rest. Your current arrangement stays until you confirm.')}</p><div class="adjust-energy-list">${Object.entries(energyData).map(([id,e])=>`<button class="option" data-energy="${id}">${icon(e.glyph)}<span><strong>${pair(e.title)}</strong><small>${pair(e.sub)}</small></span></button>`).join('')}</div>`,t('再调一调','Adjust again')),'comeback-energy');}
function showComebackReason(){const e=energyData[comebackDraft.energy];openModal(modalShell(`<div class="modal-kora">${portrait()}<span>${pair(persona().label)} Kora · ${pair(e.title)}</span></div><h2 id="modal-title">${t('今天，是什么绊住了你？','What got in the way today?')}</h2><p class="modal-sub">${t('不用解释得很好。选一句像你的，或者直接往下走。','No perfect explanation needed. Pick what fits, or simply continue.')}</p><div class="return-reasons">${Object.keys(issueLabels).map(id=>`<button class="reason-choice" data-comeback-reason="${id}" aria-pressed="${comebackDraft.reason===id}">${icon(issueIcons[id])}${pair(issueLabels[id])}</button>`).join('')}</div><div class="reason-response" aria-live="polite">“${say(comebackDraft.reason)}”</div><button class="primary" data-action="comeback-review">${t('一起把今天调小一点','Find what fits today')} ${icon('arrow')}</button><p class="helper">${t('不想做任何安排？关掉也可以。','No plan today? You can close this, too.')}</p>`,t('听听今天的你','Meet today’s you'),1),'comeback-reason');}
function showComebackReview(){const d=comebackDraft,p=comeback.plan(state,d);openModal(modalShell(`<div class="modal-kora">${portrait()}<span>${pair(persona().label)} Kora</span></div><h2 id="modal-title">${d.energy==='ready'?t('今天，按你的节奏走。','Today, at your pace.'):d.energy==='rest'?t('今天，不安排训练。','No training plan for today.'):t('把“大计划”，折小一点。','Fold that big plan into something small.')}</h2><p class="modal-sub">${d.energy==='low'?t('二选一就好。做完就停，不补过去的。','Choose just one. Stop when done. Nothing to make up.'):d.energy==='rest'?t('先把训练放下。留一点空白给自己，吃饭照常。','Set training aside. Leave some space for yourself, and eat as usual.'):t('保留已有安排；不加码，也不补练。','Keep your existing arrangement. No extras or catch-up.')}</p>${d.energy==='low'?`<div class="tiny-options">${['walk','stretch'].map(action=>`<button data-comeback-action="${action}" aria-pressed="${d.action===action}">${icon(action==='walk'?'walk':'yoga')}<strong>${smallTitle({type:'tiny',action})}</strong><small>${action==='walk'?t('走到窗边，或在房间里走走','To the window, or around your room'):t('在舒服的范围内，慢慢活动','Move slowly, within a comfortable range')}</small></button>`).join('')}</div>`:''}<div class="return-review"><small>${t('确认后，今天的安排','Your arrangement after confirmation')}</small><strong>${d.energy==='rest'?t('安心休息 · 留一小段空白','Rest · leave a little space'):smallTitle(p)}</strong><p>${d.energy==='ready'?t('原有计划与提醒保持不变。','Your plan and reminder stay as they are.'):t('替换今天尚未完成的训练，取消今晚训练提醒；餐食记录保留。','Replaces today’s unfinished training and removes its reminder. Meal records stay.')}</p></div><div class="modal-actions"><button class="text-link" data-action="comeback-back">${t('再说说','Go back')}</button><button class="primary" data-action="comeback-confirm">${t('就这样，接着来','This fits. Let’s carry on')} ${icon('check')}</button></div>`,t('一起确认','Decide together'),2),'comeback-review');}
function confirmComeback(){if(!comeback.confirm(state,comebackDraft)){closeModal();toast(t('安排或日期已经变化，请重新选择。已有记录没有被覆盖。','The date or plan changed. Please choose again. Existing records were kept.'));return;}comebackDraft=null;const saved=save();render();showComebackSuccess();if(!saved)toast(t('浏览器未能保存，仅本次页面保留。','Could not save. This arrangement lasts only for this session.'));}
function showComebackSuccess(){openModal(modalShell(`<div class="success">${portrait(state.profile.persona,'success-art')}<h2 id="modal-title">${t('好，就按今天的你来。','Good. A plan that meets you today.')}</h2><p class="modal-sub">${say(todayCare()?.energy==='rest'?'tired':'return')}</p><p>${t('安排已经留下。做完再告诉我；选择休息也不用觉得亏欠。','Your arrangement is saved. Tell me when you’re done. Rest carries no debt.')}</p><button class="primary" data-action="back-today">${t('回到我的今天','Back to my day')} ${icon('arrow')}</button></div>`,t('接上了','Back together'),3),'comeback-success');}

function today(){const p=state.plan,rest=p.type==='rest',rescheduled=p.type==='reschedule',c=todayCare(),energy=c?.energy||'welcome',done=c?.done||p.done;return `<div class="comeback-home mood-${energy} ${done?'mood-done':''}"><section class="hero return-hero" aria-labelledby="home-title"><div class="hero-copy"><p class="greeting">${t('给减脂路上，想半途而废的你','FOR THE DAYS YOU FEEL LIKE GIVING UP')}</p><h1 id="home-title"><span class="headline-line"><span>${t('不用重新开始。','No need to restart.')}</span></span><span class="headline-line"><span class="headline-accent">${t('我们接着来。','Let’s carry on.')}<i class="headline-stroke" aria-hidden="true"></i></span></span></h1><p class="hero-description">${t('没练的那几天，不用补。<br>把今天调成你做得到的样子。','No making up for the days you missed.<br>Let’s make today something you can do.')}</p><div class="hero-actions"><button class="primary" ${done?'data-route="chat"':'data-energy="low"'}>${done?t('和 Kora 待一会','Stay a while with Kora'):t('今天，只想做一点','Just a little today')} ${icon('arrow')}</button><button class="text-link" data-prompt="return">${t('我又想放弃了','I feel like giving up')} ${icon('chat')}</button></div><p class="return-promise">${t('不补账 · 不清零 · 不用证明你很自律','No catching up. No resets. No discipline to prove.')}</p></div><div class="hero-art return-scene"><span class="scene-label">${icon(done?'check':energy==='rest'?'moon':'leaf')}${done?t('这一小步，我看见了','I saw your little step'):c?pair(energyData[energy].tag):t('你回来，我就在','Whenever you return, I’m here')}</span><span class="hero-wordmark" aria-hidden="true">kora.</span><div class="scene-ground" aria-hidden="true"></div><div class="hero-kora kora-live" data-kora-live="${state.profile.persona}">${portrait(state.profile.persona,'companion-source')}<canvas aria-hidden="true"></canvas></div><div class="companion-speech"><small>${escapeHTML(state.profile.name)} · ${pair(persona().label)} Kora</small><p>“${say(done?'done':energy==='rest'?'tired':'return')}”</p></div><div class="companion-controls" hidden><button data-kora-greet>${t('打个招呼','Say hello')} ↗</button><span aria-hidden="true">·</span><button data-kora-pause aria-pressed="false" data-pause="${t('暂停动作','Pause motion')}" data-resume="${t('继续陪伴','Resume motion')}" data-reduced="${t('静态陪伴','Still companion')}">${t('暂停动作','Pause motion')}</button></div></div></section>${lifeHome()}${anchorCard()}${pathSection()}<details class="everyday-tools"><summary><span>${t('饮食、运动和日历，都还在。','Your meals, movement and calendar are still here.')}</span><small>${t('需要的时候，再展开','Open when you need them')} ＋</small></summary><div class="tool-links"><button data-route="food">${icon('bowl')}${t('好好吃饭','Meals')} ↗</button><button data-route="move">${icon('move')}${t('找个运动','Movement')} ↗</button><button data-route="chat">${icon('chat')}${t('和 Kora 聊聊','Talk to Kora')} ↗</button></div><div class="dashboard-grid"><section class="panel"><div class="plan-header"><h3>${t('今天的安排','Today’s plan')}</h3><span>${t('演示计划 · 可调整','Demo plan · adjustable')}</span></div><div class="task-row"><span class="task-thumb peach">${icon('bowl')}</span><div class="task-main"><h4>${t('好好吃一顿','Enjoy a meal')}</h4><p>${t('燕麦水果碗 · 也可以换成喜欢的','Oats and fruit · or something you enjoy')}</p></div><button class="check ${state.mealDone?'done':''}" data-action="meal-done" aria-pressed="${state.mealDone}" aria-label="${state.mealDone?t('取消餐食完成标记','Unmark meal'):t('标记餐食已完成','Mark meal done')}">${state.mealDone?icon('check'):''}</button></div><div class="task-row"><span class="task-thumb">${icon(rest?'moon':'move')}</span><div class="task-main"><h4>${planTitle()}</h4><p>${planWhen()}</p></div>${rest||rescheduled?`<span class="task-pill">${t('已调整','Adjusted')}</span>`:`<button class="check ${p.done?'done':''}" data-action="training-done" aria-pressed="${p.done}" aria-label="${p.done?t('取消运动完成标记','Unmark movement'):t('标记运动已完成','Mark movement done')}">${p.done?icon('check'):''}</button>`}</div><div class="plan-foot">${icon('bell')}<span>${t('站内提醒：','On-page reminder: ')}${reminderText()}</span></div>${state.undo?`<button class="text-link" data-action="undo">${t('撤销最近一次调整','Undo last adjustment')} ↶</button>`:''}</section><section class="panel"><div class="week-head"><h3>${t('这一周','This week')}</h3><small>${displayDate(state.date)}</small></div>${weekStrip()}<div class="week-legend"><span>${t('按真实日期保存','Saved by date')}</span><span>${planWhen()}</span></div>${historySummary()}</section></div></details><div class="prototype-note">${t('陪伴流程原型 · 对话为情境演示，记录仅保存在本浏览器','Companion prototype · scripted conversations, records saved in this browser only')}</div></div>`;}
const foods=[{id:'rice',name:['熟米饭','Cooked rice'],cal:130},{id:'banana',name:['香蕉','Banana'],cal:89},{id:'egg',name:['水煮鸡蛋','Boiled egg'],cal:155},{id:'chicken',name:['熟鸡胸肉','Cooked chicken breast'],cal:165},{id:'broccoli',name:['熟西兰花','Cooked broccoli'],cal:35},{id:'oat',name:['原味干燕麦','Plain dry oats'],cal:389}];
const recipes=[{name:['燕麦、香蕉与蓝莓','Oats, banana & blueberries'],sub:['温暖一点，早晨也慢一点。','A warm, unhurried morning.'],detail:['燕麦加热后放入香蕉和蓝莓；按喜好选择奶或植物饮品。','Warm the oats, add banana and blueberries, and use milk or a plant drink you enjoy.'],note:['含燕麦；使用奶时注意乳制品相关忌口。','Contains oats. Check dairy restrictions when adding milk.']},{name:['蔬菜三文鱼碗','Salmon & vegetable bowl'],sub:['把喜欢的颜色，放进同一碗。','A bowl of colors you enjoy.'],detail:['搭配熟米饭、充分烹熟的三文鱼和喜欢的蔬菜。','Combine cooked rice, thoroughly cooked salmon and vegetables you enjoy.'],note:['含鱼类，请按已确认的过敏与忌口替换。','Contains fish. Adapt to known allergies and dietary restrictions.']},{name:['鸡蛋杂粮饭','Egg & whole-grain rice'],sub:['家里有的食材，也能好好吃。','A good meal with what is at home.'],detail:['用熟杂粮饭、全熟鸡蛋与蔬菜组合。','Combine cooked whole grains, fully cooked eggs and vegetables.'],note:['含鸡蛋，份量按实际需要决定。','Contains eggs. Choose portions that fit your needs.']}];
function foodName(log){const f=foods.find(f=>f.id===log.foodId||f.name[0]===log.name||f.name[1]===log.name);return f?pair(f.name):log.name;}
function food(){return `${intro(t('饮食','Food'),t('好好吃饭。','Food is care.'),t('记下这一餐，看看下一餐的灵感。','Log this meal. Find ideas for the next.'))}${koraNote('food')}<div class="two-col"><section class="panel"><h3>${t('记下这一餐','Log a meal')}</h3><form id="food-form" novalidate><div class="inline-form"><div class="field"><label class="label" for="food-name">${t('吃了什么','Food')}</label><select id="food-name">${foods.map(f=>`<option value="${f.id}">${pair(f.name)}</option>`).join('')}</select></div><div class="field"><label class="label" for="food-grams">${t('实际份量 / 克','Portion / grams')}</label><input id="food-grams" type="number" min="1" max="2000" value="100" required></div></div><div class="estimate"><strong id="food-estimate">130</strong><span>kcal</span><small>${t('按份量估算','Estimated from portion')}</small></div><button class="primary" type="submit">${t('保存这一餐','Save meal')} ${icon('check')}</button><p class="helper">${t('此处为演示营养值，尚未接入正式数据库。烹饪方式和配料会影响实际热量。','Sample nutrition values, not a connected database. Cooking methods and ingredients affect actual calories.')}</p></form></section><section class="panel"><div class="plan-header"><h3>${t('今天的餐食记录','Today’s meal log')}</h3><span>${state.logs.length} ${t('条','entries')}</span></div>${state.logs.length?state.logs.map(l=>`<div class="log-item"><div><strong>${escapeHTML(foodName(l))}</strong><small>${l.grams} g · ${t('估算','est.')} ${l.cal} kcal</small></div><button data-delete-log="${escapeHTML(l.id)}" aria-label="${t('删除','Delete ')+escapeHTML(foodName(l))}">${t('删除','Delete')}</button></div>`).join(''):`<div class="empty kora-empty">${portrait(state.profile.persona)}<p>${t('还没有记录。<br>从这一餐开始就好。','Nothing logged yet.<br>Start with this meal.')}</p></div>`}<p class="helper">${t('只呈现已记录内容，不据此评价全天饮食。','Only logged meals are shown. This is not an assessment of your whole day.')}</p></section></div><div class="section-head" style="margin-top:36px"><h2>${t('下一餐的灵感','Ideas for your next meal')}</h2><span class="helper">${t('示例搭配','Sample combinations')}</span></div><div class="recipe-grid">${recipes.map((r,i)=>`<article class="recipe"><div class="recipe-art">${plate(i).replace('示意餐盘插画',t('示意餐盘插画','Illustrated sample meal'))}</div><div class="card-body"><h3>${pair(r.name)}</h3><p>${pair(r.sub)}</p><button class="text-link" data-recipe="${i}">${t('看看这份搭配','See this idea')} ↗</button></div></article>`).join('')}</div>`;}
const workouts=[{id:'light',name:['低冲击有氧','Low-impact cardio'],minutes:10,kind:'cardio',noJump:true,glyph:'walk',author:'growingannanas',url:'https://www.youtube.com/@growingannanas'},{id:'strength',name:['自重力量训练','Bodyweight strength'],minutes:20,kind:'strength',noJump:false,glyph:'move',author:'Pamela Reif',url:'https://www.youtube.com/@PamelaRf1'},{id:'stretch',name:['全身舒展','Full-body stretch'],minutes:10,kind:'stretch',noJump:true,glyph:'yoga',author:'Yoga With Adriene',url:'https://www.youtube.com/@yogawithadriene'}];
function filterLabel(id){return id==='all'?t('全部','All'):id==='noJump'?t('不跳跃','No jumping'):activityLabel(id);}
function move(){const items=filter==='all'?workouts:workouts.filter(w=>w.kind===filter||(filter==='noJump'&&w.noJump));return `${intro(t('运动','Move'),t('动一动，也可以慢一点。','Move at your own pace.'),t('按今天的时间和状态，选择一个安排。','Choose a plan that fits today’s time and energy.'))}${koraNote('move')}<p class="preference-line">${t('你喜欢：','Your interests: ')}${state.profile.activities.map(activityLabel).join(' · ')} <button class="text-link" data-route="profile">${t('修改','Edit')}</button></p><div class="filter-bar">${['all','cardio','strength','stretch','noJump'].map(id=>`<button class="filter-chip ${filter===id?'active':''}" data-filter="${id}" aria-pressed="${filter===id}">${filterLabel(id)}</button>`).join('')}</div><div class="exercise-grid">${items.map(w=>`<article class="exercise-card"><div class="exercise-art">${icon(w.glyph)}<span class="duration">${w.minutes} MIN</span></div><div class="card-body"><h3>${pair(w.name)}</h3><div class="tags"><span>${w.noJump?t('不跳跃','No jumping'):t('力量','Strength')}</span><span>${t('无器械','No equipment')}</span></div><p>${t('演示安排','Demo session')} · ${w.minutes} ${t('分钟','min')}<br>${t('作者频道参考：','Creator channel: ')}${w.author}</p><div class="exercise-actions"><button class="secondary" data-workout="${w.id}">${t('调整为这个安排','Use this session')}</button><a class="text-link" href="${w.url}" target="_blank" rel="noopener noreferrer">${t('作者频道','Creator channel')} ↗</a></div></div></article>`).join('')}</div><div class="gentle-note">${t('这些是原型训练卡片，外链仅到作者频道，尚未核验具体视频。运动偏好只作展示，不代表已进行适用性评估。','These are sample sessions. Links open creator channels, not verified videos. Preferences are displayed, not evaluated for suitability.')}</div><button class="text-link" data-issue="tired">${t('今天想休息一下','Take a rest today')} ${icon('arrow')}</button>`;}
function chat(){return `${intro(t('聊聊','Chat'),t('我在，慢慢说。','I’m here. Take your time.'),t('今天过得怎么样？','How has your day been?'))}<div class="chat-layout"><section class="chat-panel"><div class="chat-status">${portrait(state.profile.persona)}<div><strong>${pair(persona().label)} Kora</strong><small>${t('情境演示 · 未接入 AI','Scripted demo · AI not connected')}</small></div><button class="text-link change-persona" data-route="profile">${t('换性格','Switch')}</button></div><div class="messages" id="messages" role="log" aria-live="polite">${chatMessages()}</div><form class="chat-input" id="chat-form"><input id="chat-text" maxlength="500" placeholder="${t('比如：今天加班，只剩10分钟……','Try: I only have 10 minutes today…')}" aria-label="${t('告诉 Kora 今天的状态','Tell Kora how you feel')}" autocomplete="off"><button type="submit" aria-label="${t('发送消息','Send message')}">${icon('send')}</button></form><div class="chat-helper">${t('对话仅在当前页面内存中保留，不上传。','Messages stay in this page’s memory and are not uploaded.')}</div></section><aside class="companion-panel">${portrait(state.profile.persona)}<h3>${pair(persona().label)} Kora</h3><p>${pair(persona().tag)}</p><div class="quick-prompts">${['time','return','guilt','tired'].map(id=>`<button data-prompt="${id}">${pair(issueLabels[id])}</button>`).join('')}</div></aside></div>`;}
function replyBody(topic,id){if(topic==='injury')return t('先暂停当前训练，不要忍痛继续。这个原型不能判断伤情。疼痛明显、不能负重或症状加重时，请寻求专业医疗评估；紧急情况请联系当地急救服务。','Pause the activity rather than pushing through pain. This prototype cannot assess injuries. Seek medical assessment for significant pain, inability to bear weight or worsening symptoms; contact local emergency services for emergencies.');const extra={time:['可以缩短为10分钟、休息或改到明天。我先列出改动，你来决定。','We can try ten minutes, rest, or move it to tomorrow. You review the changes first.'],tired:['想调整的话，我们一起看看休息或轻活动的选项。','If you want, we can look at rest or gentle movement.'],return:['不补练。只看看今天适合哪一种安排。','No catch-up exercise. Just a plan that fits today.'],guilt:['不用少吃一餐或多练来补偿。想说说感受，我也在。','No skipped meals or extra exercise to compensate. I can listen, too.'],fallback:['这里是预设情境演示。可以试试没时间、疲劳、中断或吃完自责；开放式 AI 对话还未接入。','This is a scripted demo. Try time pressure, tiredness, a break in your routine or food guilt. Open-ended AI chat is not connected.']};return say(topic,id)+'\n'+pair(extra[topic]||extra.fallback);}
function chatMessages(){return `<div class="message">${escapeHTML(say('hello'))}</div>`+chats.map(m=>`<div class="message ${m.role==='user'?'user':''}">${m.role==='user'?escapeHTML(m.text):`<small class="reply-persona">${pair(persona(m.persona).label)} Kora</small>${escapeHTML(replyBody(m.topic,m.persona))}`}${m.role!=='user'&&issueLabels[m.topic]?`<br><button class="primary" ${m.topic==='return'?'data-energy="low"':`data-issue="${m.topic}"`}>${t('一起看看可选安排','Explore the options')} ${icon('arrow')}</button>`:''}</div>`).join('');}
function profile(){const p=profileDraft||state.profile;return `${intro(t('我的档案','My profile'),t('你的日常，你来决定。','Your everyday. Your way.'),t('首次填写的资料都在这里，随时可以修改。','Everything from setup is here. Change it whenever you need.'))}${lifeProfile()}<section class="profile-personality"><div class="section-head"><h2>${t('我的 Kora','My Kora')}</h2><span class="helper">${t('选择后，点击下方保存生效','Choose, then save below to apply')}</span></div>${personaCards(p.persona,true)}</section><div class="profile-layout"><section class="panel"><div class="profile-avatar">${portrait(p.persona)}<div><h2>${t('我的基本资料','My details')}</h2><small>${t('与首次设置同步','Synced from your first setup')}</small></div></div><form id="profile-form" novalidate>${profileFields(p)}<p class="form-error" id="form-error" role="alert"></p><button class="primary" type="submit">${t('保存我的档案','Save my profile')} ${icon('check')}</button></form></section><section class="panel"><h3>${t('你始终掌握选择权','You stay in control')}</h3><ul class="privacy-list"><li>${t('资料留在这个浏览器','Your details stay here')}<small>${t('昵称、身高、体重、偏好和演示记录仅存于此浏览器，没有账号或云同步。','Name, height, weight, preferences and demo records are stored in this browser only. No account or cloud sync.')}</small></li><li>${t('性格变，边界不变','Different voices. Same care.')}<small>${t('不羞辱身材，不鼓励节食或忍痛训练。修改档案不会自动改写已有计划。','No body shaming, restrictive dieting or training through pain. Profile edits do not automatically rewrite your plan.')}</small></li><li>${t('历史是参考，不是标签','History is a reference')}<small>${t('计划和餐食按日期保存，旧版无日期记录单独保留。','Plans and meals are saved by date. Earlier undated records are kept separately.')}</small></li></ul>${state.legacy?`<button class="secondary" data-action="legacy">${t('查看旧版无日期记录','View undated earlier records')}</button>`:''}<div><button class="danger" data-action="reset">${t('清除本地数据，重新开始','Clear local data & start again')}</button></div><p class="helper">${storageOK?t('本地保存可用。','Local storage available.'):t('本地保存不可用，仅本次页面保留。','Local storage unavailable. Session only.')}</p></section></div><section class="soft-banner"><p>${t('Kora 可以和你一起变化。','Kora can grow alongside you.')}</p><small>${t('体型联动仍是待讨论方向。当前身高和体重只作档案记录，不计算目标体型、减重期限或自动改变考拉体型。','Body-shape linking remains a future idea. Measurements are profile records only; they do not calculate a target body, weight-loss timeline or change Kora’s shape.')}</small></section>`;}

function openModal(content,view){if(!$('#modal').open)modalOpener=document.activeElement;modalView=view;$('#modal-content').innerHTML=content;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function closeModal(){comebackDraft=null;draft=null;lifePlanDraft=null;modalView=null;$('#modal').close();if(modalOpener?.isConnected)modalOpener.focus();}
function modalShell(content,kicker=t('调整计划','Adjust plan'),step=0){return `<div class="modal-inner"><div class="modal-top"><span class="eyebrow">${kicker}</span><div class="modal-tools">${languageControl()}<button class="close" data-action="close" aria-label="${t('关闭','Close')}">×</button></div></div>${step?`<div class="steps" aria-label="${t('第'+step+'步，共3步','Step '+step+' of 3')}">${[1,2,3].map(n=>`<span class="${n<=step?'active':''}"></span>`).join('')}</div>`:''}${content}</div>`;}
function startIssue(issue){if(state.plan.done||todayCare()?.done){openModal(modalShell(`<h2 id="modal-title">${t('已经完成的，保留就好。','Keep what you have already done.')}</h2><p class="modal-sub">${t('不把已经完成的行动改写成休息或改期。可以先聊聊，明天再做新安排。','Completed activities will not be replaced with rest or rescheduled. Let us talk, or plan another day.')}</p><button class="primary" data-action="go-chat">${t('和 Kora 聊聊','Talk to Kora')}</button>`),'completed');return;}draft={issue,choice:null,date:state.date,base:JSON.stringify(state.plan)};showChoices();}
function showChoices(){const guilt=draft.issue==='guilt';openModal(modalShell(`<div class="modal-kora">${portrait(state.profile.persona)}<span>${pair(persona().label)} Kora</span></div><h2 id="modal-title">${say(draft.issue)}</h2><p class="modal-sub">${t('先选一个适合现在的安排。确认之前，不会改变计划。','Choose what fits right now. Nothing changes until you confirm.')}</p>${guilt?`<button class="option" data-action="go-chat">${icon('chat')}<span><strong>${t('先聊聊，不改计划','Just talk, keep the plan')}</strong><small>${t('不用把情绪立刻变成任务。','Feelings do not have to become a task.')}</small></span></button>`:''}${(guilt?['rest']:['short','rest','reschedule']).map(option).join('')}<div class="modal-actions"><button class="text-link" data-action="close">${t('保持原计划','Keep current plan')}</button></div>`,t('选择安排','Choose a plan'),1),'choices');}
function option(id){const data={short:['walk',['做一点就好','A little movement'],['10分钟轻活动 · 不跳跃 · 不补练','10 gentle minutes · no jumping or catch-up']],rest:['moon',['今天，安心休息','Take a rest today'],['取消今晚训练提醒，饮食照常','Remove tonight’s workout reminder; eat as usual']],reschedule:['refresh',['把训练留给明天','Move it to tomorrow'],['今天不催促 · 明天20:00再提醒','No pressure tonight · tomorrow at 20:00']]}[id];return `<button class="option" data-choice="${id}">${icon(data[0])}<span><strong>${pair(data[1])}</strong><small>${pair(data[2])}</small></span><span class="radio"></span></button>`;}
function draftPlan(){if(draft.workout){const w=workouts.find(w=>w.id===draft.workout);return{type:'custom',workout:w.id,minutes:w.minutes,day:2,done:false,reminder:true};}if(draft.choice==='rest')return{type:'rest',minutes:0,day:2,done:false,reminder:false};if(draft.choice==='reschedule')return{...state.plan,type:'reschedule',minutes:state.plan.minutes||Number(state.profile.minutes),day:3,done:false,reminder:false};return{type:'short',workout:'light',minutes:10,day:2,done:false,reminder:true};}
function showConfirm(){const next=draftPlan();openModal(modalShell(`<h2 id="modal-title">${t('这样调整，可以吗？','Does this work for you?')}</h2><p class="modal-sub">${t('你点确认之后，这些改动才会生效。','These changes apply only after you confirm.')}</p><div class="compare"><div><small>${t('原来的安排','Current plan')}</small><strong>${planTitle()}</strong><p>${planWhen()}</p></div><span aria-hidden="true">→</span><div><small>${t('调整后的安排','Proposed plan')}</small><strong>${planTitle(next)}</strong><p>${planWhen(next)}</p></div></div><div class="change-row"><span>${t('本周安排','This week')}</span><b>${next.day===3?t('今天留白，训练改到明天','Today free; workout tomorrow'):next.type==='rest'?t('今天改为休息，其余保持','Rest today; other days unchanged'):t('更新今天，其余保持','Update today; other days unchanged')}</b></div><div class="change-row"><span>${t('站内提醒','On-page reminder')}</span><b>${next.reminder?t('今晚20:00 · 更新安排','Tonight 20:00 · updated'):next.day===3?t('改到明天20:00','Move to tomorrow 20:00'):t('今晚取消','Removed for tonight')}</b></div><div class="change-row"><span>${t('饮食安排','Meals')}</span><b>${t('照常吃饭，不做补偿','Eat as usual; no compensation')}</b></div><div class="modal-actions"><button class="text-link" data-action="back-options">${t('再想一想','Reconsider')}</button><button class="primary" data-action="confirm-plan">${t('确认，就这样安排','Confirm this plan')} ${icon('check')}</button></div>`,t('确认改动','Review changes'),2),'confirm');}
function showSuccess(){openModal(modalShell(`<div class="success">${portrait(state.profile.persona,'success-art')}<h2 id="modal-title">${t('安排已更新。','Plan updated.')}</h2><p class="modal-sub">${say(state.plan.type==='rest'?'tired':'done')}</p><div class="gentle-note">${t('今天、本周与站内提醒已同步，随时可以撤销最近一次调整。','Today, this week and the on-page reminder are in sync. You can undo the last adjustment.')}</div><div class="modal-actions"><button class="primary" data-action="back-today">${t('看看我的今天','Back to my day')} ${icon('arrow')}</button></div></div>`,t('调整完成','All set'),3),'success');}
function commitDraft(){if(!draft)return;if(draft.date!==state.date||draft.base!==JSON.stringify(state.plan)){closeModal();toast(t('计划已经变化，请重新选择。','The plan changed. Please choose again.'));return;}if(!calendar.adjust(state,draftPlan(),draft.workout||draft.issue)){closeModal();toast(t('目标日期已有安排或记录已变化，未覆盖已有记录。','That date has a plan or records changed. Existing records were kept.'));return;}draft=null;const saved=save();render();showSuccess();if(!saved)toast(t('仅本次页面保留，浏览器未能保存。','Session only: the browser could not save this change.'));}
function showAbout(){openModal(modalShell(`<h2 id="modal-title">${t('你的 Kora，你的节奏。','Your Kora. Your pace.')}</h2><p class="modal-sub">${t('同一份陪伴，四种语气。中断后，还能继续。','One kind of care, four different voices. A fresh start whenever you need it.')}</p><div class="about-points"><p><strong>${t('01 · 先认识彼此','01 · Get to know each other')}</strong><span>${t('先测生活人格，再选搭子语气、补资料。结果同步到首页推荐和档案。','Discover your lifestyle, choose Kora’s voice, then add your details. Results sync with home recommendations and Profile.')}</span></p><p><strong>${t('02 · 安慰，变成可执行的调整','02 · Care becomes an actionable change')}</strong><span>${t('缩短、休息、改期，确认后才更新。性格不同，照顾你的边界一致。','Shorten, rest or reschedule, after your confirmation. Different personalities share the same care.')}</span></p><p><strong>${t('03 · 在关键时刻出现','03 · There at the right moments')}</strong><span>${t('首页问候、聊天、空记录和完成反馈，都是你选的那只 Kora。','Your chosen Kora appears in greetings, chat, empty logs and completion feedback.')}</span></p></div><p class="helper">${t('这是前端原型，没有登录账号、后端或真实 AI。聊天是双语预设情境，食物和训练是演示数据。基本资料仅存于本地浏览器；没有照片评估、社群、真实通知或自动体型联动。','This is a frontend prototype without sign-in, a backend or real AI. Chat uses bilingual scripted scenarios; food and exercise data are samples. Details stay in local browser storage. Photo assessment, communities, real notifications and body-shape linking are not implemented.')}</p><div class="modal-actions"><button class="primary" data-action="close">${t('知道了','Got it')}</button></div>`,t('关于 Kora','About Kora')),'about');}
function showRecipe(n){const r=recipes[n];openModal(modalShell(`<h2 id="modal-title">${pair(r.name)}</h2><p class="modal-sub">${pair(r.detail)}</p><div class="gentle-note">${pair(r.note)}<br>${t('这是搭配灵感，不是个人营养处方。','This is a meal idea, not a personal nutrition prescription.')}</div><button class="primary" data-action="close">${t('记下这个灵感','Got the idea')}</button>`,t('餐食灵感','Meal inspiration')),'recipe:'+n);}
function showReset(){openModal(modalShell(`<h2 id="modal-title">${t('清除资料，重新开始？','Clear your details and start again?')}</h2><p class="modal-sub">${t('这会清除这个浏览器里的昵称、身高、体重、性格、偏好、餐食和计划记录，回到首次选择流程。','This clears your name, measurements, personality, preferences, meal logs and plans in this browser, then returns to setup.')}</p><div class="modal-actions"><button class="secondary" data-action="close">${t('先保留','Keep my data')}</button><button class="primary" data-action="confirm-reset">${t('确认清除','Clear my data')}</button></div>`,t('本地数据','Local data')),'reset');}
function refreshModal(){if(modalView==='life-plan'){showLifePlan();return;}if(modalView==='comeback-energy'){showComebackEnergy();return;}if(modalView==='comeback-reason'){showComebackReason();return;}if(modalView==='comeback-review'){showComebackReview();return;}if(modalView==='comeback-success'){showComebackSuccess();return;}if(modalView==='choices')showChoices();else if(modalView==='confirm')showConfirm();else if(modalView==='success')showSuccess();else if(modalView==='about')showAbout();else if(modalView==='legacy')showLegacy();else if(modalView?.startsWith('history:'))showHistory(modalView.slice(8));else if(modalView==='reset')showReset();else if(modalView==='completed')startIssue('time');else if(modalView?.startsWith('recipe:'))showRecipe(Number(modalView.split(':')[1]));}
function sendChat(text){text=text.trim();if(!text)return;let topic='fallback';if(/疼|痛|受伤|扭伤|流血|晕|胸闷|pain|hurt|injur|dizz|bleed|chest|faint/i.test(text))topic='injury';else if(/自责|吃多|暴食|胖|失败|补偿|饿|少吃|guilt|overeat|binge|fat\b|starv|skip.*meal|compensat/i.test(text))topic='guilt';else if(/加班|没时间|分钟|忙|busy|no time|minute|overtime|short on time/i.test(text))topic='time';else if(/没记录|几天|中断|回来|坚持|放弃|半途|been away|back|missed|days|restart|give up|giving up|quit/i.test(text))topic='return';else if(/累|疲|不想|休息|tired|rest|exhaust|worn out/i.test(text))topic='tired';chats.push({role:'user',text},{role:'kora',topic,persona:state.profile.persona});if(currentRoute!=='chat')route('chat');else{$('#messages').innerHTML=chatMessages();$('#messages').scrollTop=$('#messages').scrollHeight;$('#chat-text').value='';}}
function setLanguage(lang){if(!['zh','en'].includes(lang)||state.language===lang)return;captureForm();const foodDraft=$('#food-form')?{id:$('#food-name').value,grams:$('#food-grams').value}:null;const chatDraft=$('#chat-text')?.value;state.language=lang;save();render();if(foodDraft){$('#food-name').value=foodDraft.id;$('#food-grams').value=foodDraft.grams;updateEstimate();}if(chatDraft!==undefined&&$('#chat-text'))$('#chat-text').value=chatDraft;refreshModal();$('#toast').classList.remove('toast-visible');$('#toast').innerHTML='';}
function lifeStyle(id){const d=lifestyle.types[id];return `--life-soft:${d.soft};--life-color:${d.color}`;}
function lifeArt(id,cls=''){return `<img class="${cls}" src="assets/kora-life-${id}-v4.png" alt="${escapeHTML(pair(lifestyle.types[id].name)+' Kora')}">`;}
function lifeGallery(){return `<div class="life-gallery">${Object.entries(lifestyle.types).map(([id,d])=>`<article class="life-tile" style="${lifeStyle(id)}">${lifeArt(id)}<small>${d.code}</small><h2>${pair(d.name)}</h2><p>${pair(d.tag)}</p></article>`).join('')}</div>`;}
function lifeFacts(r){return `<div class="life-facts"><span>${activityLabel(r.activities[0])}</span><span>${r.minutes} ${t('分钟空档','min available')}</span><span>${pair(lifestyle.timeLabels[r.preferredTime])}</span></div>`;}
function saveQuizDraft(){try{if(quizSession)sessionStorage.setItem('kora.quiz.draft',JSON.stringify(quizSession));else sessionStorage.removeItem('kora.quiz.draft');}catch{}}
function quizRender(){saveQuizDraft();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});}
function beginQuiz(){captureForm();quizSession={phase:'intro',index:0,answers:[]};quizRender();}
function quizView(){
 const q=quizSession||{phase:'intro',index:0,answers:[]};
 const top=`<div class="life-top"><span class="eyebrow">KORA / ${t('生活人格研究所','THE EVERYDAY YOU')}</span>${state.onboarded?`<button class="text-link" data-life="exit">${t('先返回，不保存','Leave without saving')} ×</button>`:''}</div>`;
 if(q.phase==='intro')return `<section class="life-page">${top}<div class="life-intro"><p class="eyebrow">${t('不是每只考拉，都用同一种方式坚持。','EVERY KORA HAS A DIFFERENT WAY TO KEEP GOING.')}</p><h1>${t('你的身体里，<br>住着哪只考拉？','Which Kora<br>feels like you?')}</h1><p>${t('六个生活小场景，找到更适合你的开始方式。','Six everyday moments. Find a way to start that fits you.')}</p></div>${lifeGallery()}<div class="life-start"><button class="primary" data-life="start">${t('测测我的考拉人格','Meet my Kora type')} ${icon('arrow')}</button><p class="life-disclaimer">${t('约 1 分钟 · 没有标准答案 · 可以随时重测<br>趣味生活偏好测试，不是 MBTI 或心理测评。','About 1 minute · No right answers · Retake anytime<br>A playful preference quiz, not an MBTI or psychological assessment.')}</p></div></section>`;
 if(q.phase==='result'){
  const r=lifestyle.result(q.answers);if(!r)return '';
  const d=lifestyle.types[r.type];
  return `<section class="life-page">${top}<div class="life-result" style="${lifeStyle(r.type)}"><div class="life-result-art">${lifeArt(r.type)}<span>${d.code} / KORA</span></div><div><p class="eyebrow">${t('找到你了，你更像……','THERE YOU ARE. YOU’RE MOST LIKE…')}</p><h1>${pair(d.name)}<span class="sr-only"> Kora</span></h1><p class="life-result-quote">“${pair(d.quote)}”</p><p class="life-result-care">${pair(d.care)}</p>${lifeFacts(r)}<p class="life-disclaimer">${t('根据日常、遇到中断和需要的支持来匹配；同分时参考第一题。不是固定标签，也不使用身高体重判断。','Matched from your everyday habits, pauses and preferred support; the first answer breaks ties. A flexible preference, never based on your measurements.')}</p><div class="life-actions"><button class="primary" data-life="accept">${state.onboarded?t('保存结果，同步到我的日常','Save & sync my preferences'):t('下一步，选我的陪伴搭子','Next, choose my companion')} ${icon('arrow')}</button><button class="text-link" data-life="restart">${t('重新测一次','Take it again')}</button><button class="text-link" data-life="download">${t('保存人格卡片','Save my type card')} ↓</button></div><p class="life-disclaimer">${state.onboarded?t('保存会更新运动与时长偏好；已有计划和历史记录保留。','Saving updates movement and time preferences. Existing plans and history stay.'):t('你是哪种考拉，和搭子用什么语气陪你，可以自由搭配。','Your Kora type and your companion’s voice are yours to mix and match.')}</p><p id="life-export-status" role="status"></p></div></div><details class="life-all-types"><summary>${t('认识另外几只考拉','Meet the other Kora types')}</summary>${lifeGallery()}</details></section>`;
 }
 const question=lifestyle.questions[q.index],selected=q.answers[q.index],art=['lazy','spark','busy','feel','lazy','feel'][q.index];
 return `<section class="life-page">${top}<div class="life-question"><aside class="life-question-art">${lifeArt(art)}<p>${t('不用表现得很好，像你自己就好。','No perfect performance. Just be yourself.')}</p></aside><div><div class="life-progress" aria-label="${t('第','Question ')}${q.index+1} / 6">${lifestyle.questions.map((_,i)=>`<span class="${i<=q.index?'complete':''}"></span>`).join('')}</div><p class="eyebrow">0${q.index+1} / 06</p><h1 id="life-question-title">${pair(question.title)}</h1><p class="life-hint">${pair(question.hint)}</p><div class="life-options" role="group" aria-labelledby="life-question-title">${question.options.map((o,i)=>`<button class="life-option" data-life-answer="${o.id}" aria-pressed="${selected===o.id}"><span aria-hidden="true">${selected===o.id?'✓':String.fromCharCode(65+i)}</span><span>${pair(o.label)}</span></button>`).join('')}</div><div class="life-question-actions"><button class="text-link" data-life="previous">← ${q.index?t('上一题','Previous'):t('返回介绍','Introduction')}</button><button class="primary" data-life="next" ${!selected?'disabled':''}>${q.index===5?t('看看我的考拉','Meet my Kora'):t('下一题','Next')} ${icon('arrow')}</button></div></div></div></section>`;
}
function lifeHome(){
 const r=state.profile.lifestyle;
 if(!lifestyle.valid(r))return `<section class="life-home"><div class="life-mini-art">${lifeArt('lazy')}</div><div class="life-home-copy"><p class="eyebrow">${t('认识自己，再开始','A LITTLE SELF-DISCOVERY')}</p><h2>${t('你是哪一种考拉？','Which Kora are you?')}</h2><p>${t('六道题，把计划调成更像你的样子。','Six questions. A starting point that feels more like you.')}</p><div class="life-actions"><button class="primary" data-life="open">${t('测测我的生活人格','Find my Kora type')} ${icon('arrow')}</button></div></div></section>`;
 const d=lifestyle.types[r.type],suggestion=lifestyle.recommendation(state.profile),blocked=state.plan.done||todayCare()?.done||state.plan.type==='rest';
 return `<section class="life-home" style="${lifeStyle(r.type)}">${lifeArt(r.type)}<div class="life-home-copy"><p class="eyebrow">${pair(d.name)} · ${t('适合你的起步方式','YOUR WAY TO BEGIN')}</p><h2>${blocked?t('今天的选择，先好好留着。','Let today’s choice be enough.'):suggestion.checkIn?t('先问问今天的心情。','How are you feeling today?'):planTitle(suggestion.plan)}</h2><p>${blocked?t('已完成的行动和休息日都不加码。偏好已记住，下次开始时再用。','No extras on a completed or rest day. Your preferences are ready for your next start.'):pair(d.care)}</p><div class="life-actions">${!blocked?`<button class="primary" ${suggestion.checkIn?'data-action="comeback-energy"':'data-life="plan"'}>${suggestion.checkIn?t('看看今天的状态','Check in with myself'):t('看看这个安排','Review this suggestion')} ${icon('arrow')}</button>`:''}<button class="text-link" data-route="profile">${t('查看我的人格与偏好','My type & preferences')} ↗</button></div></div></section>`;
}
function lifeProfile(){
 const r=state.profile.lifestyle;if(!lifestyle.valid(r))return lifeHome();const d=lifestyle.types[r.type];
 return `<section class="life-profile" style="${lifeStyle(r.type)}">${lifeArt(r.type)}<div><p class="eyebrow">${t('我的生活人格 · 与搭子的语气分开','MY LIFESTYLE · SEPARATE FROM KORA’S VOICE')}</p><h2>${pair(d.name)} · ${d.code}</h2><p>“${pair(d.quote)}”</p>${lifeFacts({...r,activities:state.profile.activities,minutes:state.profile.minutes})}<div class="life-actions"><button class="text-link" data-life="open">${t('重新测试','Retake the quiz')} ↗</button><button class="text-link" data-life="download-saved">${t('保存人格卡片','Save my type card')} ↓</button></div><p class="life-disclaimer">${t('运动和时长可在下方修改；偏好时间可通过重测修改，不会自动开启通知。','Edit movement and time below. Retake to change your preferred time of day. Notifications are not enabled.')}</p><p id="life-export-status" role="status"></p></div></section>`;
}
function showLifePlan(){
 if(!lifePlanDraft)return;
 openModal(modalShell(`<h2 id="modal-title">${t('让今天更像你的节奏。','Let today move at your pace.')}</h2><p class="modal-sub">${t('这是根据你的生活偏好生成的起步建议，可以不采用。','A starting suggestion based on your preferences. You can keep your current plan.')}</p><div class="life-review"><small>${t('目前的安排','Current plan')}</small><strong>${planTitle()}</strong></div><div class="life-review"><small>${t('确认后，今天改为','After you confirm')}</small><strong>${planTitle(lifePlanDraft.plan)}</strong></div><p>${t('只替换今天未完成的训练，取消它的站内提醒。餐食与历史记录保留；可以撤销。','Replaces today’s unfinished session and removes its on-page reminder. Meals and history stay; you can undo.')}</p><div class="modal-actions"><button class="text-link" data-action="close">${t('保留原计划','Keep my plan')}</button><button class="primary" data-life="confirm-plan">${t('采用这个安排','Use this suggestion')} ${icon('check')}</button></div>`,t('人格推荐 · 你来确认','YOUR STYLE · YOUR CHOICE')),'life-plan');
}
async function downloadLifeCard(r){
 if(!lifestyle.valid(r))return;
 const en=state.language==='en',d=lifestyle.types[r.type],msg=document.getElementById('life-export-status');
 try{
  if(msg)msg.textContent=t('正在制作卡片……','Making your card…');
  const img=new Image();img.src=`assets/kora-life-${r.type}-v4.png`;await img.decode();
  const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const ctx=canvas.getContext('2d');
  ctx.fillStyle=d.soft;ctx.fillRect(0,0,1080,1350);ctx.fillStyle=d.color;
  ctx.font='600 34px sans-serif';ctx.fillText('kora. / THE EVERYDAY YOU',70,90);
  ctx.drawImage(img,140,145,800,800);ctx.textAlign='center';ctx.font='600 68px sans-serif';ctx.fillText(d.name[en?1:0],540,1020);ctx.font='24px sans-serif';ctx.fillText(d.code+' · '+d.tag[en?1:0],540,1080);
  ctx.font='28px sans-serif';const words=en?d.quote[1].split(' '):[...d.quote[0]];let line='',y=1160;for(const word of words){const next=line+(en&&line?' ':'')+word;if(ctx.measureText(next).width>900){ctx.fillText(line,540,y);y+=42;line=word;}else line=next;}ctx.fillText(line,540,y);
  ctx.font='20px sans-serif';ctx.fillText(en?'A playful preference. You can change.':'趣味生活偏好 · 你可以有很多种样子',540,1295);
  const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('export');
  const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Kora-${d.code}-${en?'en':'zh'}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  if(msg)msg.textContent=en?'Card ready. Check your browser downloads.':'卡片已生成，请查看浏览器下载。';
 }catch{if(msg)msg.textContent=t('暂时无法生成卡片，请重试。','Could not create the card. Please try again.');}
}
function handleLifeClick(b){
 if(b.dataset.lifeAnswer&&quizSession?.phase==='questions'){
  const answer=b.dataset.lifeAnswer;if(!lifestyle.questions[quizSession.index].options.some(o=>o.id===answer))return true;
  quizSession.answers[quizSession.index]=answer;saveQuizDraft();render();document.querySelector(`[data-life-answer="${answer}"]`)?.focus({preventScroll:true});return true;
 }
 const action=b.dataset.life;if(!action)return false;
 if(action==='open'){beginQuiz();return true;}
 if(action==='exit'){quizSession=null;saveQuizDraft();render();return true;}
 if(action==='start'||action==='restart'){quizSession={phase:'questions',index:0,answers:[]};quizRender();return true;}
 if(action==='download'||action==='download-saved'){downloadLifeCard(action==='download'?lifestyle.result(quizSession?.answers):state.profile.lifestyle);return true;}
 if(action==='previous'&&quizSession){if(quizSession.index===0)quizSession.phase='intro';else quizSession.index--;quizRender();return true;}
 if(action==='next'&&quizSession){if(!quizSession.answers[quizSession.index])return true;if(quizSession.index===5){if(!lifestyle.result(quizSession.answers))return true;quizSession.phase='result';}else quizSession.index++;quizRender();return true;}
 if(action==='accept'&&quizSession){
  const r=lifestyle.result(quizSession.answers);if(!r)return true;
  if(state.onboarded){state.profile=lifestyle.apply(state.profile,r);if(profileDraft)profileDraft=lifestyle.apply(profileDraft,r);}else{setupDraft=lifestyle.apply(setupDraft,r);state.profile=structuredClone(setupDraft);}
  quizSession=null;saveQuizDraft();const saved=save();render();window.scrollTo(0,0);
  if(state.onboarded)toast(saved?t('人格与偏好已同步。现有计划保留，新建议由你确认。','Type and preferences synced. Your current plan stays until you choose.'):t('暂时无法保存，只在本次页面保留。','Could not save. Session only.'));return true;
 }
 if(action==='plan'&&state.onboarded){const rec=lifestyle.recommendation(state.profile);if(!rec||rec.checkIn||state.plan.done||todayCare()?.done||state.plan.type==='rest')return true;lifePlanDraft={plan:rec.plan,date:state.date,base:JSON.stringify(state.plan)};showLifePlan();return true;}
 if(action==='confirm-plan'&&lifePlanDraft){
  const d=lifePlanDraft;if(d.date!==state.date||d.base!==JSON.stringify(state.plan)||!calendar.adjust(state,d.plan,'lifestyle')){closeModal();toast(t('安排已经变化，请重新查看建议。','Your plan changed. Please review the suggestion again.'));return true;}
  // Keep the existing completion/undo journey available for this confirmed suggestion.
  state.days[state.date].comeback={energy:'ready',reason:'return',action:d.plan.action,done:false,at:new Date().toISOString()};
  closeModal();render();persistNotice(t('今天的安排已更新，可以随时撤销。','Today’s plan is updated. You can undo it.'));return true;
 }
 return true;
}
document.addEventListener('click',event=>{
 if(refreshDate())return;
 const b=event.target.closest('button,[data-route]');if(!b)return;
 if(b.dataset.lang){setLanguage(b.dataset.lang);return;}
 if(handleLifeClick(b))return;
 if(b.dataset.action==='about'){showAbout();return;}if(b.dataset.action==='close'){closeModal();return;}
 if(b.dataset.persona){captureForm();if(!state.onboarded)setupDraft.persona=b.dataset.persona;else{profileDraft=profileDraft||structuredClone(state.profile);profileDraft.persona=b.dataset.persona;}render();return;}
 if(b.dataset.action==='setup-next'&&!state.onboarded&&PERSONA_IDS.includes(setupDraft.persona)){setupStep=2;render();window.scrollTo(0,0);$('#profile-name').focus();return;}
 if(b.dataset.action==='setup-back'&&!state.onboarded){captureForm();setupStep=1;render();window.scrollTo(0,0);return;}
 if(!state.onboarded)return;
 if(b.dataset.energy){startComeback(b.dataset.energy);return;}
 if(b.dataset.comebackReason&&comebackDraft){comebackDraft.reason=b.dataset.comebackReason;showComebackReason();return;}
 if(b.dataset.comebackAction&&comebackDraft){comebackDraft.action=b.dataset.comebackAction;showComebackReview();return;}
 if(b.dataset.week){weekOffset+=Number(b.dataset.week);render();return;}if(b.dataset.historyDate){showHistory(b.dataset.historyDate);return;}
 if(b.dataset.route){if(quizSession){quizSession=null;saveQuizDraft();}route(b.dataset.route);return;}if(b.dataset.issue){startIssue(b.dataset.issue);return;}if(b.dataset.choice&&draft){draft.choice=b.dataset.choice;showConfirm();return;}
 if(b.dataset.filter){filter=b.dataset.filter;render();return;}if(b.dataset.prompt){sendChat(pair(issueLabels[b.dataset.prompt]));return;}
 if(b.dataset.deleteLog){state.logs=state.logs.filter(l=>l.id!==b.dataset.deleteLog);render();persistNotice(t('已删除这条餐食记录。','Meal entry deleted.'));return;}
 if(b.dataset.workout){if(state.plan.done||todayCare()?.done){toast(t('已完成的行动不会被替换。','Completed activities will not be replaced.'));return;}draft={workout:b.dataset.workout,date:state.date,base:JSON.stringify(state.plan)};showConfirm();return;}
 if(b.dataset.recipe!==undefined){showRecipe(Number(b.dataset.recipe));return;}
 switch(b.dataset.action){
 case 'comeback-energy':showComebackEnergy();break;
 case 'comeback-review':if(comebackDraft)showComebackReview();break;
 case 'comeback-back':if(comebackDraft)showComebackReason();break;
 case 'comeback-confirm':b.disabled=true;confirmComeback();break;
 case 'comeback-complete':if(comeback.complete(state)){render();persistNotice(returnMessage());}break;
 case 'back-options':draft?.workout?closeModal():showChoices();break;
 case 'confirm-plan':b.disabled=true;commitDraft();break;
 case 'back-today':closeModal();route('today');break;
 case 'go-chat':closeModal();route('chat');break;
 case 'meal-done':state.mealDone=!state.mealDone;render();persistNotice(state.mealDone?say('done'):t('已取消完成标记。','Completion mark removed.'));break;
 case 'training-done':state.plan.done=!state.plan.done;if(todayCare())todayCare().done=state.plan.done;state.plan.reminder=!state.plan.done;state.undo=null;render();persistNotice(state.plan.done?say('done'):t('已取消运动完成标记。','Movement completion mark removed.'));break;
 case 'undo':if(calendar.undo(state)){render();persistNotice(t('已恢复上一次安排和改期日期。','Previous plan and reservation restored.'));}else toast(t('目标日期已有新记录，无法撤销。','The target date has new records; undo is unavailable.'));break;
 case 'legacy':showLegacy();break;
 case 'this-week':weekOffset=0;render();break;
 case 'reset':showReset();break;
 case 'confirm-reset':{const language=state.language;try{localStorage.removeItem(STORAGE_KEY);}catch{toast(t('未能清除浏览器数据，请在浏览器设置中清除。','Could not clear saved data. Please use browser settings.'));return;}state=freshState();state.language=language;quizSession=null;saveQuizDraft();setupStep=1;setupDraft=structuredClone(state.profile);profileDraft=null;chats.length=0;filter='all';closeModal();render();window.scrollTo(0,0);break;}
 }
});
function updateEstimate(){const f=foods.find(f=>f.id===$('#food-name').value),grams=Number($('#food-grams').value);$('#food-estimate').textContent=Number.isFinite(grams)&&grams>0&&grams<=2000?Math.round(f.cal*grams/100):'—';}
document.addEventListener('input',e=>{if(['food-name','food-grams'].includes(e.target.id))updateEstimate();});
document.addEventListener('change',e=>{if(e.target.id==='food-name')updateEstimate();});
document.addEventListener('submit',event=>{
 event.preventDefault();if(refreshDate())return;const id=event.target.id;
 if(id==='setup-form'||id==='profile-form'){
  const p=readProfileForm(id==='setup-form'?setupDraft:(profileDraft||state.profile));const error=profileError(p);if(error){$('#form-error').textContent=error;$('#form-error').setAttribute('tabindex','-1');$('#form-error').focus();return;}
  state.profile=p;const first=id==='setup-form';state.onboarded=true;profileDraft=null;setupDraft=structuredClone(p);const saved=save();if(first){location.hash='today';currentRoute='today';lastAnimatedRoute=null;}render();window.scrollTo(0,0);toast(saved?(first?t('资料已同步到档案。欢迎和 Kora 一起开始。','Your details are in Profile. Welcome to life with Kora.'):t('档案已保存，性格已同步。现有计划不变。','Profile and personality saved. Your existing plan is unchanged.')):t('浏览器未能保存，当前资料仅在本次页面保留。','Could not save. Your details last only for this session.'));return;
 }
 if(!state.onboarded)return;
 if(id==='food-form'){const f=foods.find(f=>f.id===$('#food-name').value),grams=Number($('#food-grams').value);if(!Number.isFinite(grams)||grams<1||grams>2000){toast(t('请输入1—2000克之间的实际份量。','Enter a portion from 1 to 2000 grams.'));return;}state.logs.push({date:state.date,at:new Date().toISOString(),id:String(Date.now())+String(Math.random()).slice(2,6),foodId:f.id,grams,cal:Math.round(f.cal*grams/100)});render();persistNotice(t('这一餐已记下。','Meal logged.'));}
 if(id==='chat-form')sendChat($('#chat-text').value);
});
